/*table-real:recorder*/ (() => {
  const w = window;
  const write = (record) => w.__oracleWrite(JSON.stringify(record));
  const tree = w.__oracleTree;
  const renderer = w.tabs.tabList[w.tabs.selectedTab].renderer;
  const sel = w.selection;
  const watched = ["setHoveredTime", "setSelectedTime", "goIdle", "play", "pause", "lock", "unlock"];
  const render = renderer.render;
  renderer.render = function (command) {
    write({ tr: "render", command: tree(command) });
    const saved = watched.map((name) => sel[name]);
    watched.forEach((name, i) => {
      sel[name] = (...args) => {
        write({ tr: "selection", call: tree([name, ...args]) });
        return saved[i].apply(sel, args);
      };
    });
    try {
      render.call(this, command);
      write({ tr: "rendered", range: tree(this.getTimestampRange()) });
    } catch (error) {
      write({ tr: "rendered", threw: tree(String(error)) });
    } finally {
      watched.forEach((name, i) => (sel[name] = saved[i]));
    }
  };
  renderer.TABLE_BODY.addEventListener("mousemove", (event) => write({ tr: "mousemove", y: tree(event.clientY) }));
  renderer.TABLE_BODY.addEventListener("mouseleave", () => write({ tr: "mouseleave" }));
})()
